const supplied = $input.first().json.domains;
const domains = supplied === undefined ? ['stripe.com', 'vercel.com', 'gitlab.com'] : supplied;
if (!Array.isArray(domains) || domains.length === 0 || domains.length > 10) throw new Error('Supply between 1 and 10 domains for this starter workflow.');
for (const domain of domains) {
  if (typeof domain !== 'string' || !domain.trim()) throw new Error('Each domain must be a nonempty string.');
  if (!/^(?:https?:\/\/)?(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}(?::[0-9]{1,5})?(?:[/?#][^\s]*)?$/i.test(domain.trim())) throw new Error('Invalid website domain.');
}
return [{ json: { domains: domains.map(domain => domain.trim()), maxDomains: domains.length, mode: 'resolve', includeUnresolved: true, concurrency: 3 } }];

const data = $input.first().json.data;
if (!data || typeof data.id !== 'string' || !data.id) throw new Error('Malformed actor run response.');
if (data.status === 'SUCCEEDED') {
  if (typeof data.defaultDatasetId !== 'string' || !data.defaultDatasetId) throw new Error('Successful run has no dataset ID.');
  return [{ json: { ...data, routeIndex: 0 } }];
}
if (!['READY', 'RUNNING', 'ABORTING', 'TIMING-OUT'].includes(data.status)) throw new Error('Actor failed or returned an unsupported status: ' + data.status);
const started = Date.parse(data.startedAt || data.createdAt);
if (!Number.isFinite(started) || started > Date.now() + 60000) throw new Error('Run response has an invalid timestamp.');
if (Date.now() - started > 1020000) throw new Error('Polling exceeded seventeen minutes; inspect the run in Apify Console.');
return [{ json: { ...data, routeIndex: 1 } }];

const items = $input.all();
if (items.length === 0) throw new Error('The actor returned no company rows.');
return items.map((item, index) => {
  const row = item.json;
  if (!row || typeof row.domain !== 'string' || !row.domain) throw new Error('Empty or malformed company dataset.');
  const validCompanyUrl = typeof row.linkedinUrl === 'string' && /^https:\/\/(?:www\.)?linkedin\.com\/company\/[^/?#\s]+(?:[/?#]|$)/i.test(row.linkedinUrl);
  return { json: { ...row, needsReview: !(['high', 'medium'].includes(row.confidence) && validCompanyUrl) }, pairedItem: { item: index } };
});
